'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var TWO_PI = require( '@stdlib/constants/float64/two-pi' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var sin = require( '@stdlib/math/base/special/sin' );
var cos = require( '@stdlib/math/base/special/cos' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );
var floor = require( '@stdlib/math/base/special/floor' );
var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
var rfftf = require( './../lib' );


// VARIABLES //

// Test cases covering various FFT sizes including prime factors 2, 3, 4, 5, and general primes
var nd = [ 120, 91, 54, 49, 32, 28, 24, 8, 4, 3, 2 ];


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rfftf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( rfftf.length, 7, 'has expected arity' );
	t.end();
});

tape( 'the function returns early if `N` is 1 (identity transform)', function test( t ) {
	var workspace;
	var x;

	workspace = new Float64Array( 36 );
	rffti( 1, workspace, 1, 0 );

	x = new Float64Array( [ 5.0 ] );
	rfftf( 1, x, 1, 0, workspace, 1, 0 );

	t.strictEqual( x[ 0 ], 5.0, 'returns expected value' );
	t.end();
});

tape( 'the function computes the forward real FFT (N=2)', function test( t ) {
	var workspace;
	var x;

	workspace = new Float64Array( 38 );
	rffti( 2, workspace, 1, 0 );

	x = new Float64Array( [ 1.0, 2.0 ] );
	rfftf( 2, x, 1, 0, workspace, 1, 0 );

	// Expected: DC = 1+2 = 3, Nyquist = 1-2 = -1
	t.strictEqual( x[ 0 ], 3.0, 'DC component is correct' );
	t.strictEqual( x[ 1 ], -1.0, 'Nyquist component is correct' );
	t.end();
});

tape( 'the function computes the forward real FFT (N=4)', function test( t ) {
	var workspace;
	var x;

	workspace = new Float64Array( 42 );
	rffti( 4, workspace, 1, 0 );

	x = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	rfftf( 4, x, 1, 0, workspace, 1, 0 );

	// Expected output: [ 10, -2, 2, -2 ]
	t.strictEqual( x[ 0 ], 10.0, 'DC component is correct' );
	t.strictEqual( abs( x[ 1 ] - (-2.0) ) < 1e-14, true, 'Re(k=1) is correct' );
	t.strictEqual( abs( x[ 2 ] - 2.0 ) < 1e-14, true, 'Im(k=1) is correct' );
	t.strictEqual( abs( x[ 3 ] - (-2.0) ) < 1e-14, true, 'Nyquist is correct' );
	t.end();
});

tape( 'the function computes the forward real FFT matching DFT definition', function test( t ) {
	var workspace;
	var error;
	var sum1;
	var sum2;
	var arg1;
	var modn;
	var tol;
	var err;
	var nm1;
	var ns2;
	var arg;
	var dt;
	var nz;
	var n;
	var x;
	var y;
	var i;
	var j;
	var k;

	tol = 1e-10;

	for ( nz = 0; nz < nd.length; nz++ ) {
		n = nd[ nz ];

		x = new Float64Array( n );
		y = new Float64Array( n );
		workspace = new Float64Array( ( n * 2 ) + 34 );

		modn = n % 2;
		nm1 = n - 1;

		// Initialize input with test signal: sin(j * sqrt(2))
		for ( j = 1; j <= n; j++ ) {
			x[ j - 1 ] = sin( j * SQRT2 );
		}

		// Initialize workspace
		rffti( n, workspace, 1, 0 );

		// Compute expected DFT result manually
		dt = TWO_PI / n;
		ns2 = floor( ( n + 1 ) / 2 );

		// Compute non-DC, non-Nyquist components
		if ( ns2 > 1 ) {
			for ( k = 2; k <= ns2; k++ ) {
				sum1 = 0.0;
				sum2 = 0.0;
				arg = ( k - 1 ) * dt;
				for ( i = 1; i <= n; i++ ) {
					arg1 = ( i - 1 ) * arg;
					sum1 += x[ i - 1 ] * cos( arg1 );
					sum2 += x[ i - 1 ] * sin( arg1 );
				}
				y[ ( k << 1 ) - 3 ] = sum1;
				y[ ( k << 1 ) - 2 ] = -sum2;
			}
		}

		// Compute DC and Nyquist components
		sum1 = 0.0;
		sum2 = 0.0;
		for ( i = 1; i <= nm1; i += 2 ) {
			sum1 += x[ i - 1 ];
			sum2 += x[ i ];
		}
		if ( modn === 1 ) {
			sum1 += x[ n - 1 ];
		}
		y[ 0 ] = sum1 + sum2;
		if ( modn === 0 ) {
			y[ n - 1 ] = sum1 - sum2;
		}

		// Perform forward FFT
		rfftf( n, x, 1, 0, workspace, 1, 0 );

		// Compare FFT output with expected DFT result
		err = 0.0;
		for ( i = 0; i < n; i++ ) {
			error = abs( x[ i ] - y[ i ] );
			err = max( err, error );
		}
		err /= n;

		t.ok( err <= tol, 'N=' + n + ': forward transform error ' + err + ' <= ' + tol );
	}
	t.end();
});

tape( 'the function handles various radix factors correctly', function test( t ) {
	var workspace;
	var sizes;
	var err;
	var tol;
	var n;
	var x;
	var i;
	var j;

	/*
	* Test sizes that exercise different radix routines:
	*
	* -   Powers of 2: radix-2, radix-4
	* -   Multiples of 3: radix-3
	* -   Multiples of 5: radix-5
	* -   Other primes: general radix
	*/
	sizes = [
		2,    // radix-2
		3,    // radix-3
		4,    // radix-4
		5,    // radix-5
		6,    // 2*3
		7,    // general radix
		8,    // radix-4
		9,    // 3*3
		10,   // 2*5
		12,   // 2*2*3
		15,   // 3*5
		16,   // radix-4
		20,   // 2*2*5
		21,   // 3*7
		25,   // 5*5
		49,   // 7*7
		77,   // 7*11
		100   // 2*2*5*5
	];

	tol = 1e-10;

	for ( j = 0; j < sizes.length; j++ ) {
		n = sizes[ j ];

		x = new Float64Array( n );
		workspace = new Float64Array( ( n * 2 ) + 34 );

		// Initialize with simple ramp signal
		for ( i = 0; i < n; i++ ) {
			x[ i ] = i + 1;
		}

		// Initialize workspace and compute FFT
		rffti( n, workspace, 1, 0 );
		rfftf( n, x, 1, 0, workspace, 1, 0 );

		// Verify DC component equals sum of input
		err = abs( x[ 0 ] - ( n * ( n + 1 ) / 2 ) );
		t.ok( err < tol, 'N=' + n + ': DC component is sum of input (error=' + err + ')' );
	}
	t.end();
});
